import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.DyLyN3RJ.js";const g=JSON.parse('{"title":"2026-11-11 · Agent 核心研究与竞品动态","description":"","frontmatter":{"title":"2026-11-11 · Agent 核心研究与竞品动态","outline":false},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-11.md","filePath":"zh/runtime/daily-intelligence/2026-11-11.md","lastUpdated":1794364546000}'),n={name:"zh/runtime/daily-intelligence/2026-11-11.md"};function i(p,a,l,h,s,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_2026-11-11-·-agent-核心研究与竞品动态" tabindex="-1">2026-11-11 · Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-11-·-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-11 · Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮最重要的结论：企业 Agent 治理正在落实到调用身份、审批归属、回执与失败语义；而真实部署与测试通过之间仍有明显鸿沟。Paperclip 的预发布事故是反例，Orca 的跨主机编排也仍有未启用部分。以下 26 项事实观察支撑 6 组分析，分析不另算新增事件。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><h3 id="o1-·-codex-取消与恢复的执行身份" tabindex="-1">O1 · Codex：取消与恢复的执行身份 <a class="header-anchor" href="#o1-·-codex-取消与恢复的执行身份" aria-label="Permalink to &quot;O1 · Codex：取消与恢复的执行身份&quot;">​</a></h3><p>取消后正确终结 turn，晚到的未知取消不再打断另一个显式 ID 的 turn；恢复历史里的未完成工具调用可补 aborted 结果，但新调用仍保留缺失结果检查。aborted 只表示中断，不能证明外部副作用未发生。</p><p><a href="https://github.com/openai/codex/pull/60700" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-11T02:14:15Z</a>；<a href="https://github.com/openai/codex/pull/60519" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T04:11:58Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o2-·-codex-消息投递独立于后续推理留证" tabindex="-1">O2 · Codex：消息投递独立于后续推理留证 <a class="header-anchor" href="#o2-·-codex-消息投递独立于后续推理留证" aria-label="Permalink to &quot;O2 · Codex：消息投递独立于后续推理留证&quot;">​</a></h3><p>接受的 Agent 消息即使没有后续模型请求，也保存投递及交互边；回放沿用稳定 item ID，避免重复回执生成重复消息。这是跨 Agent 可追溯性机制，尚未据此验证端到端消息恰好一次。</p><p><a href="https://github.com/openai/codex/pull/60673" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T22:23:08Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o3-·-codex-调用时重核授权与身份版本" tabindex="-1">O3 · Codex：调用时重核授权与身份版本 <a class="header-anchor" href="#o3-·-codex-调用时重核授权与身份版本" aria-label="Permalink to &quot;O3 · Codex：调用时重核授权与身份版本&quot;">​</a></h3><p>预算检查的异步等待期间若切换账号，HTTP 重新准备，WebSocket 重核授权所有者；工作负载身份复用进一步绑定 session 与 provider/mapping/authorization 版本。普通 token 刷新可延续，身份代际变化需退役旧来源。</p><p><a href="https://github.com/openai/codex/pull/60436" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-09T19:50:49Z</a>；<a href="https://github.com/openai/codex/pull/60433" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-09T19:27:25Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o4-·-codex-企业策略模板与终止性拒绝" tabindex="-1">O4 · Codex：企业策略模板与终止性拒绝 <a class="header-anchor" href="#o4-·-codex-企业策略模板与终止性拒绝" aria-label="Permalink to &quot;O4 · Codex：企业策略模板与终止性拒绝&quot;">​</a></h3><p>有托管规则时采用可信 Guardian 模板，废弃两个旧 auto_review 配置项并给出迁移提示；推理 hook 明确拒绝、工作区拒绝不再靠重试或压缩模型回退绕行。显式 host 模板仍有保留边界。</p><p><a href="https://github.com/openai/codex/pull/60646" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T19:30:51Z</a>；<a href="https://github.com/openai/codex/pull/60511" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T03:21:57Z</a>；<a href="https://github.com/openai/codex/pull/60480" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T00:54:59Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o5-·-codex-上下文信任与工具声明的不同边界" tabindex="-1">O5 · Codex：上下文信任与工具声明的不同边界 <a class="header-anchor" href="#o5-·-codex-上下文信任与工具声明的不同边界" aria-label="Permalink to &quot;O5 · Codex：上下文信任与工具声明的不同边界&quot;">​</a></h3><p>goal objective 以不可信上下文进入模型，避免变成高权限续跑指令；自动审批中 readOnlyHint 优先于冲突的 destructive/openWorld 声明，但显式 prompt 和严格审查仍走对应检查。声明优先级不等于工具真实安全。</p><p><a href="https://github.com/openai/codex/pull/60342" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-09T03:58:32Z</a>；<a href="https://github.com/openai/codex/pull/60638" target="_blank" rel="noreferrer">openai/codex · MERGED → main · 2026-11-10T18:33:47Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o6-·-agents-python-嵌套审批归属与检查结果恢复" tabindex="-1">O6 · Agents Python：嵌套审批归属与检查结果恢复 <a class="header-anchor" href="#o6-·-agents-python-嵌套审批归属与检查结果恢复" aria-label="Permalink to &quot;O6 · Agents Python：嵌套审批归属与检查结果恢复&quot;">​</a></h3><p>RunState 记录嵌套审批归属，恢复时核对 child 与当前 parent response；同 ID/参数但不同 Agent 的调用仍区分。原审批 Agent 已被移出图则明确报错，证据不足继续拒绝恢复；审批前后 guardrail 结果保留到最终结果和 checkpoint。</p><p><a href="https://github.com/openai/openai-agents-python/pull/5629" target="_blank" rel="noreferrer">openai/openai-agents-python · MERGED → main · 2026-11-09T05:47:10Z</a>；<a href="https://github.com/openai/openai-agents-python/pull/5630" target="_blank" rel="noreferrer">openai/openai-agents-python · MERGED → main · 2026-11-09T05:47:11Z</a>；<a href="https://github.com/openai/openai-agents-python/pull/5633" target="_blank" rel="noreferrer">openai/openai-agents-python · MERGED → main · 2026-11-09T05:48:25Z</a>；<a href="https://github.com/openai/openai-agents-python/pull/5643" target="_blank" rel="noreferrer">openai/openai-agents-python · MERGED → main · 2026-11-09T06:56:10Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o7-·-agents-python-流式请求前重核-guardrail" tabindex="-1">O7 · Agents Python：流式请求前重核 guardrail <a class="header-anchor" href="#o7-·-agents-python-流式请求前重核-guardrail" aria-label="Permalink to &quot;O7 · Agents Python：流式请求前重核 guardrail&quot;">​</a></h3><p>并行 input guardrail 已拒绝时，在每次流式模型尝试前重核，包括重试；尚未完成的 guardrail 仍允许并行执行，不能解读为全部模型调用都先串行验权。</p><p><a href="https://github.com/openai/openai-agents-python/pull/5644" target="_blank" rel="noreferrer">openai/openai-agents-python · MERGED → main · 2026-11-09T06:56:11Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o8-·-agents-js-审批保全、交接错误恢复与安全还原" tabindex="-1">O8 · Agents JS：审批保全、交接错误恢复与安全还原 <a class="header-anchor" href="#o8-·-agents-js-审批保全、交接错误恢复与安全还原" aria-label="Permalink to &quot;O8 · Agents JS：审批保全、交接错误恢复与安全还原&quot;">​</a></h3><p>自动压缩等待审批请求/结果配对及成功模型交换；handoff 可选 errorFunction 将可恢复错误反馈原 Agent，默认仍快速失败，已发生副作用不会撤销；UnixLocal/Docker 还原前先验证归档，坏归档不先清空原文件。</p><p><a href="https://github.com/openai/openai-agents-js/pull/2288" target="_blank" rel="noreferrer">openai/openai-agents-js · MERGED → main · 2026-11-09T11:03:56Z</a>；<a href="https://github.com/openai/openai-agents-js/pull/2290" target="_blank" rel="noreferrer">openai/openai-agents-js · MERGED → main · 2026-11-09T23:28:07Z</a>；<a href="https://github.com/openai/openai-agents-js/pull/2279" target="_blank" rel="noreferrer">openai/openai-agents-js · MERGED → main · 2026-11-09T23:30:49Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o9-·-gemini-cli-停止、信任与真实错误" tabindex="-1">O9 · Gemini CLI：停止、信任与真实错误 <a class="header-anchor" href="#o9-·-gemini-cli-停止、信任与真实错误" aria-label="Permalink to &quot;O9 · Gemini CLI：停止、信任与真实错误&quot;">​</a></h3><p>headless 收到信号时清理子进程组/PTY，立即保存 scheduled 调用，恢复无结果调用时补 interrupted 响应，并保留信号退出码；macOS 在入沙箱前解析目录信任；MessageBus 发布失败立即返回原错，但当前仓库尚无 request() 调用方。</p><p><a href="https://github.com/google-gemini/gemini-cli/pull/30204" target="_blank" rel="noreferrer">google-gemini/gemini-cli · MERGED → main · 2026-11-09T20:16:27Z</a>；<a href="https://github.com/google-gemini/gemini-cli/pull/30164" target="_blank" rel="noreferrer">google-gemini/gemini-cli · MERGED → main · 2026-11-09T20:05:57Z</a>；<a href="https://github.com/google-gemini/gemini-cli/pull/30189" target="_blank" rel="noreferrer">google-gemini/gemini-cli · MERGED → main · 2026-11-09T21:19:47Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o10-·-claude-code-oauth-与文件权限修复正式发行" tabindex="-1">O10 · Claude Code：OAuth 与文件权限修复正式发行 <a class="header-anchor" href="#o10-·-claude-code-oauth-与文件权限修复正式发行" aria-label="Permalink to &quot;O10 · Claude Code：OAuth 与文件权限修复正式发行&quot;">​</a></h3><p>发行说明列出 OAuth 重定向不再向另一主机发送 refresh token 等秘密；修复只读 Bash 沙箱外执行未提示、错误目录判写、cp/mv 目的文件未套用 deny/保护规则等问题。remote-control settings 文件变化后暂停新会话直至重启。未本地复现或确认所有安装端已升级。</p><p><a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.321" target="_blank" rel="noreferrer">anthropics/claude-code · RELEASED · 2026-11-09T19:22:30Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o11-·-mansura-habiba-技能包完整性与内部冲突" tabindex="-1">O11 · Mansura Habiba：技能包完整性与内部冲突 <a class="header-anchor" href="#o11-·-mansura-habiba-技能包完整性与内部冲突" aria-label="Permalink to &quot;O11 · Mansura Habiba：技能包完整性与内部冲突&quot;">​</a></h3><p>锁摘要覆盖全部交付文件、可执行位和路径，安装临时目录核对失败则保留旧缓存；新增 skill 内部矛盾标签，确定性规则与可选 LLM 分类均仅提示，不独自使验证失败。这是作者相关项目，仍不是 AGENTSAFE 官方 Artifact。</p><p><a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/20" target="_blank" rel="noreferrer">mansura-habiba/bulbasaur-skill-cli · MERGED → main · 2026-11-09T21:02:49Z</a>；<a href="https://github.com/mansura-habiba/bulbasaur-skill-cli/pull/19" target="_blank" rel="noreferrer">mansura-habiba/bulbasaur-skill-cli · MERGED → main · 2026-11-10T21:10:42Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o12-·-ag2-1-3-1-沙箱与协议互操作正式发行" tabindex="-1">O12 · AG2 1.3.1：沙箱与协议互操作正式发行 <a class="header-anchor" href="#o12-·-ag2-1-3-1-沙箱与协议互操作正式发行" aria-label="Permalink to &quot;O12 · AG2 1.3.1：沙箱与协议互操作正式发行&quot;">​</a></h3><p>E2B 与 boxd 后端加入共享工具环境；E2B 续期不缩短运行中命令期限，过期不静默重建。MCP Apps 对上游 ext-apps 文档保留原样，避免重复 ui/initialize；A2UI 1.0 稳定规范有消息及 catalog 校验迁移成本，不能与 MCP Apps 混作同一协议。</p><p><a href="https://github.com/ag2ai/ag2/releases/tag/v.1.3.1" target="_blank" rel="noreferrer">ag2ai/ag2 · RELEASED · 2026-11-10T21:03:11Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o13-·-mcp-apps-2-1-webmcp-双向桥" tabindex="-1">O13 · MCP Apps 2.1：WebMCP 双向桥 <a class="header-anchor" href="#o13-·-mcp-apps-2-1-webmcp-双向桥" aria-label="Permalink to &quot;O13 · MCP Apps 2.1：WebMCP 双向桥&quot;">​</a></h3><p>App.registerTool 与页面 document.modelContext 双向映射，工具变更传播到 Apps 通道；每 App 默认开启、可关闭，不新增 wire 消息和 host API。视图内工具发现面扩大，权限与声明归属需要另行核查，不能推导为 FCoP 任务协议替代品。</p><p><a href="https://github.com/modelcontextprotocol/ext-apps/releases/tag/v2.1.0" target="_blank" rel="noreferrer">modelcontextprotocol/ext-apps · RELEASED · 2026-11-10T22:53:57Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o14-·-paperclip-用事务回执恢复文档写入" tabindex="-1">O14 · Paperclip：用事务回执恢复文档写入 <a class="header-anchor" href="#o14-·-paperclip-用事务回执恢复文档写入" aria-label="Permalink to &quot;O14 · Paperclip：用事务回执恢复文档写入&quot;">​</a></h3><p>write_document 的 revision 与幂等回执同事务保存，并以 baseRevisionId CAS；孤儿调用可重放已保存结果，或在回执证明未执行时执行一次。上游将其限定于能证明结果的这类写操作，不能扩展为任意工具 exactly-once。</p><p><a href="https://github.com/paperclipai/paperclip/pull/20674" target="_blank" rel="noreferrer">paperclipai/paperclip · MERGED → master · 2026-11-11T01:05:16Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o15-·-paperclip-代办-token-与看见秘密分开" tabindex="-1">O15 · Paperclip：代办 token 与看见秘密分开 <a class="header-anchor" href="#o15-·-paperclip-代办-token-与看见秘密分开" aria-label="Permalink to &quot;O15 · Paperclip：代办 token 与看见秘密分开&quot;">​</a></h3><p>同日先以 person-only 阻断 Agent 拿到明文，再由后续合入恢复受委派创建权：Agent 只收到 pendingReveal 元数据，责任人单次 reveal 才激活凭据，并发二次 reveal 返回冲突。最终判断应以后续方案为准，旧 token 不被自动清理。</p><p><a href="https://github.com/paperclipai/paperclip/pull/20581" target="_blank" rel="noreferrer">paperclipai/paperclip · MERGED → master · 2026-11-10T17:31:44Z</a>；<a href="https://github.com/paperclipai/paperclip/pull/20613" target="_blank" rel="noreferrer">paperclipai/paperclip · MERGED → master · 2026-11-10T21:13:35Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o16-·-paperclip-验收由措辞转向状态-并暴露部署盲区" tabindex="-1">O16 · Paperclip：验收由措辞转向状态，并暴露部署盲区 <a class="header-anchor" href="#o16-·-paperclip-验收由措辞转向状态-并暴露部署盲区" aria-label="Permalink to &quot;O16 · Paperclip：验收由措辞转向状态，并暴露部署盲区&quot;">​</a></h3><p>16 个对正确成果误判的 chat case 改查持久状态、审计和页面结构，保留虚假声明检查。另一项上游预发布统计称 48 小时 276 run 失败、63 task 阻塞，而原混沌测试覆盖不到换容器/进程空间；新增 K15 redeploy 故障。统计与测试为上游证据，尚不能宣称修复所有事故。</p><p><a href="https://github.com/paperclipai/paperclip/pull/20600" target="_blank" rel="noreferrer">paperclipai/paperclip · MERGED → master · 2026-11-10T19:37:16Z</a>；<a href="https://github.com/paperclipai/paperclip/pull/20679" target="_blank" rel="noreferrer">paperclipai/paperclip · MERGED → master · 2026-11-11T02:05:18Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o17-·-orca-跨主机协调的准入骨架与聊天-cli" tabindex="-1">O17 · Orca：跨主机协调的准入骨架与聊天 CLI <a class="header-anchor" href="#o17-·-orca-跨主机协调的准入骨架与聊天-cli" aria-label="Permalink to &quot;O17 · Orca：跨主机协调的准入骨架与聊天 CLI&quot;">​</a></h3><p>paired Orca 在接收端作为真实 caller，首次同步段完成准入，目标限制到原 Run；但发送新 envelope 的协调端尚未启用，当前骨架 inert。另已合入 chat list/read/send/wait，允许桥接器或其他 Agent 继续同一聊天。两者成熟度不能混报。</p><p><a href="https://github.com/stablyai/orca/pull/40717" target="_blank" rel="noreferrer">stablyai/orca · MERGED → main · 2026-11-10T19:56:02Z</a>；<a href="https://github.com/stablyai/orca/pull/40836" target="_blank" rel="noreferrer">stablyai/orca · MERGED → main · 2026-11-10T22:37:32Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o18-·-orca-凭据继承可见与可选白名单" tabindex="-1">O18 · Orca：凭据继承可见与可选白名单 <a class="header-anchor" href="#o18-·-orca-凭据继承可见与可选白名单" aria-label="Permalink to &quot;O18 · Orca：凭据继承可见与可选白名单&quot;">​</a></h3><p>recipe 生命周期脚本仍默认继承进程环境；现在展示凭据变量名、支持 opt-in passEnv。配置错误时限到安全基础集合，而非丢弃配置后回到全量继承。默认并未变成最小权限，不能把告警当隔离已默认落实。</p><p><a href="https://github.com/stablyai/orca/pull/40757" target="_blank" rel="noreferrer">stablyai/orca · MERGED → main · 2026-11-11T01:58:07Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o19-·-orca-定时任务醒时计时与故障分类" tabindex="-1">O19 · Orca：定时任务醒时计时与故障分类 <a class="header-anchor" href="#o19-·-orca-定时任务醒时计时与故障分类" aria-label="Permalink to &quot;O19 · Orca：定时任务醒时计时与故障分类&quot;">​</a></h3><p>启动时限只计 awake time，短 DarkWake 不启动补跑，真正醒稳后再追赶；未真正启动单独标记。relay 对已长时间静默的主机在授权过期检查时标为 silence timeout，授权仍结束，修正的是归因而非延长授权。与我们漏跑问题相关，但不能据此断言同根因。</p><p><a href="https://github.com/stablyai/orca/pull/40943" target="_blank" rel="noreferrer">stablyai/orca · MERGED → main · 2026-11-11T01:43:31Z</a>；<a href="https://github.com/stablyai/orca/pull/40929" target="_blank" rel="noreferrer">stablyai/orca · MERGED → main · 2026-11-11T00:19:46Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o20-·-orkas-兼容性探测失败先停派发" tabindex="-1">O20 · Orkas：兼容性探测失败先停派发 <a class="header-anchor" href="#o20-·-orkas-兼容性探测失败先停派发" aria-label="Permalink to &quot;O20 · Orkas：兼容性探测失败先停派发&quot;">​</a></h3><p>OpenCode run --help 失败时不再把空 flags 当安全命令继续执行；返回可重试的兼容错误且不缓存失败。上游报告 macOS Electron 故障/重试路径通过，未声明付费 provider、Windows GUI 或安装包已验收。</p><p><a href="https://github.com/Orkas-AI/Orkas/pull/195" target="_blank" rel="noreferrer">Orkas-AI/Orkas · MERGED → main · 2026-11-10T03:56:18Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o21-·-vibe-kanban-acp-registry-与动态配置" tabindex="-1">O21 · Vibe Kanban：ACP registry 与动态配置 <a class="header-anchor" href="#o21-·-vibe-kanban-acp-registry-与动态配置" aria-label="Permalink to &quot;O21 · Vibe Kanban：ACP registry 与动态配置&quot;">​</a></h3><p>新增从 ACP registry 安装 Agent、保持聊天历史；需要 Node/npx 与先在终端登录。后续合入从 Agent 动态读取模型并按 model→reasoning→mode 应用配置，Plan 不支持时回 Ask，不能回 Auto。虽任务标注 sunset，真实新增值得低频重查，不代表商业运营恢复。</p><p><a href="https://github.com/BloopAI/vibe-kanban/pull/3489" target="_blank" rel="noreferrer">BloopAI/vibe-kanban · MERGED → main · 2026-11-10T06:10:43Z</a>；<a href="https://github.com/BloopAI/vibe-kanban/pull/3496" target="_blank" rel="noreferrer">BloopAI/vibe-kanban · MERGED → main · 2026-11-10T10:58:32Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o22-·-openhands-sdk-运行中纠偏、损坏事件与虚假成功" tabindex="-1">O22 · OpenHands SDK：运行中纠偏、损坏事件与虚假成功 <a class="header-anchor" href="#o22-·-openhands-sdk-运行中纠偏、损坏事件与虚假成功" aria-label="Permalink to &quot;O22 · OpenHands SDK：运行中纠偏、损坏事件与虚假成功&quot;">​</a></h3><p>socket 在 step 运行时就接收并保存消息，即使客户端离开；坏事件文件以同 ID 的不可读错误占位，保留索引/seq 而不伪造模型内容；域名策略拦导航时真实返回 is_error，避免模型误以为已访问。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6709" target="_blank" rel="noreferrer">OpenHands/software-agent-sdk · MERGED → main · 2026-11-10T00:23:30Z</a>；<a href="https://github.com/OpenHands/software-agent-sdk/pull/6669" target="_blank" rel="noreferrer">OpenHands/software-agent-sdk · MERGED → main · 2026-11-09T21:20:16Z</a>；<a href="https://github.com/OpenHands/software-agent-sdk/pull/6661" target="_blank" rel="noreferrer">OpenHands/software-agent-sdk · MERGED → main · 2026-11-10T13:08:07Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o23-·-dspy-3-5-可运行推理组件与迁移成本" tabindex="-1">O23 · DSPy 3.5：可运行推理组件与迁移成本 <a class="header-anchor" href="#o23-·-dspy-3-5-可运行推理组件与迁移成本" aria-label="Permalink to &quot;O23 · DSPy 3.5：可运行推理组件与迁移成本&quot;">​</a></h3><p>RLM/Flex/GEPA 转为稳定公共模块；ReAct 替换、History 与类型化 submit、lm15 默认路由带来提示词/默认值/API 变化，必须重新评测优化程序。RLM History 只保存对话，不恢复活解释器变量；稳定称谓本身不构成安全或持久化保证。</p><p><a href="https://github.com/stanfordnlp/dspy/releases/tag/3.5.0" target="_blank" rel="noreferrer">stanfordnlp/dspy · RELEASED · 2026-11-10T16:25:47Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o24-·-agentlas-windows-旧安装升级边界" tabindex="-1">O24 · Agentlas：Windows 旧安装升级边界 <a class="header-anchor" href="#o24-·-agentlas-windows-旧安装升级边界" aria-label="Permalink to &quot;O24 · Agentlas：Windows 旧安装升级边界&quot;">​</a></h3><p>实际 Windows 旧版升级发现盘符大小写使旧插件 pin 未迁移，已按文件系统比较路径并避免前缀相似兄弟目录误命中；同系列处理 host 重启后插件绑定回退。是安装迁移成熟度证据，不等于所有主机升级均验证。</p><p><a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.95" target="_blank" rel="noreferrer">agentlas-ai/Agentlas-OS · RELEASED · 2026-11-09T08:40:54Z</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。 竞品学习价值、竞争风险与雷达判断见 A6。</p><h3 id="o25-·-langchain-企业平台实例与验收方法" tabindex="-1">O25 · LangChain：企业平台实例与验收方法 <a class="header-anchor" href="#o25-·-langchain-企业平台实例与验收方法" aria-label="Permalink to &quot;O25 · LangChain：企业平台实例与验收方法&quot;">​</a></h3><p>11 月 10 日官方客户案例称 Workday 用内部 SDK、LLM/RAG 网关和 API 治理层承接 LangGraph/LangSmith，A2A/MCP 在其 server 层采用；这是供应商案例主张，未独立核验。11 月 9 日评测文章主张为行为同时定义应做、不应做、保留能力，按结果状态验收并留出未调参测试集。</p><p><a href="https://www.langchain.com/blog/how-workday-built-an-enterprise-scale-ai-agent-platform-with-langgraph-and-langsmith" target="_blank" rel="noreferrer">LangChain / Workday · PUBLISHED CASE STUDY · 2026-11-10</a>；<a href="https://www.langchain.com/blog/what-is-eval-driven-development" target="_blank" rel="noreferrer">LangChain / Workday · PUBLISHED ENGINEERING GUIDE · 2026-11-09</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h3 id="o26-·-openai-business-agents-的角色与授权政策" tabindex="-1">O26 · OpenAI：Business Agents 的角色与授权政策 <a class="header-anchor" href="#o26-·-openai-business-agents-的角色与授权政策" aria-label="Permalink to &quot;O26 · OpenAI：Business Agents 的角色与授权政策&quot;">​</a></h3><p>11 月 10 日政策更新要求 Agent 明示代表的企业与 AI 身份、保持信息准确，并在批准角色及用户授权内行动，收集或转交信息需对应授权。范围是 ChatGPT 中代表企业的 Business Agents，属于平台产品边界，不能直接视作通用多 Agent 协议规范。</p><p><a href="https://openai.com/policies/business-agents-policy/" target="_blank" rel="noreferrer">OpenAI Business Agents · POLICY UPDATED · 2026-11-10</a></p><p>验证限制：上游一手资料，未本地实测；归类为持续观察/资料留存，候选见分析层。</p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><h3 id="a1-·-o3-o4-o5-o6-o15-o18-o26" tabindex="-1">A1 · O3 / O4 / O5 / O6 / O15 / O18 / O26 <a class="header-anchor" href="#a1-·-o3-o4-o5-o6-o15-o18-o26" aria-label="Permalink to &quot;A1 · O3 / O4 / O5 / O6 / O15 / O18 / O26&quot;">​</a></h3><p>授权要随执行对象和代际重核，代办权限不必等于接触秘密。证据支持调用前重核、审批归属、秘密单次揭示的不同机制；待验证的是把它们接到 CodeFlowMu 岗位委派与凭据代理后，是否能覆盖跨员工/组织切换。主要落在 Runtime/适配与产品治理层，不直接新增 FCoP 内核规则。实验候选：审批后换身份、移除原 Agent、并发 reveal。互动议题：授权版本变化后，已批准但未执行的动作如何失效？</p><h3 id="a2-·-o1-o2-o8-o9-o14-o17-o22" tabindex="-1">A2 · O1 / O2 / O8 / O9 / O14 / O17 / O22 <a class="header-anchor" href="#a2-·-o1-o2-o8-o9-o14-o17-o22" aria-label="Permalink to &quot;A2 · O1 / O2 / O8 / O9 / O14 / O17 / O22&quot;">​</a></h3><p>协作交付需要区分投递、接受、执行、结果与恢复证据。中断记录不证明副作用未发生；事务回执只在其保护的资源上提供较强恢复依据。待验证：FCoP 工件中的任务/事件/结果语义，能否与 Runtime 的调用身份、回执及 unknown outcome 正确对应；不要把持久化、调度和所有权实现全推给协议。实验候选：执行后掉回执、消息接受后不再推理、损坏事件文件与断连纠偏。</p><h3 id="a3-·-o7-o10-o11-o13-o18-o20-o22" tabindex="-1">A3 · O7 / O10 / O11 / O13 / O18 / O20 / O22 <a class="header-anchor" href="#a3-·-o7-o10-o11-o13-o18-o20-o22" aria-label="Permalink to &quot;A3 · O7 / O10 / O11 / O13 / O18 / O20 / O22&quot;">​</a></h3><p>治理必须看真实边界与失败行为。默认继承环境、advisory 冲突标签、readOnly 声明与真正拦截不是同一级保证。已支持的判断是：失败应保留原错、阻断不安全派发且不虚报成功。体验候选：bulbasaur 技能包锁定和冲突检查；先核验安装方式、许可与维护成本，当前未安装。互动议题：运行时重新读取策略失败时如何保持拒绝语义？</p><h3 id="a4-·-o12-o13-o17-o21-o23-o25" tabindex="-1">A4 · O12 / O13 / O17 / O21 / O23 / O25 <a class="header-anchor" href="#a4-·-o12-o13-o17-o21-o23-o25" aria-label="Permalink to &quot;A4 · O12 / O13 / O17 / O21 / O23 / O25&quot;">​</a></h3><p>互操作应按层比较：MCP Apps/WebMCP 是视图工具面，ACP 是客户端与 Agent 会话配置，A2A 是跨 Agent 接口；Orca 的跨机协调仍有 inert 段。FCoP 的文件/工件协调可与这些互补，现有证据不证明是同层替代。体验候选：ACP registry 应用与 AG2/MCP Apps；代价包括 Node/登录、协议版本、host 支持、沙箱服务与成本。DSPy 3.5 则先做独立迁移评测，不直接当数字员工成品。</p><h3 id="a5-·-o16-o22-o23-o25" tabindex="-1">A5 · O16 / O22 / O23 / O25 <a class="header-anchor" href="#a5-·-o16-o22-o23-o25" aria-label="Permalink to &quot;A5 · O16 / O22 / O23 / O25&quot;">​</a></h3><p>独立验收要查留下的状态，并让故障模型接近真实部署。Paperclip 的预发布反例与 LangChain 的结果验收建议相互呼应；它们支持研究方法，不能推出所有项目都已解决可靠性。实验候选：同机重启对比跨进程空间 redeploy，以任务完成、审计和副作用判定，另外保留没用于调参的案例。互动议题：K15 之后是否仍有不同 hostHash 无法判定前主死亡的阻塞类？</p><h3 id="a6-·-o14-o15-o16-o17-o18-o19-o20-o21-o24" tabindex="-1">A6 · O14 / O15 / O16 / O17 / O18 / O19 / O20 / O21 / O24 <a class="header-anchor" href="#a6-·-o14-o15-o16-o17-o18-o19-o20-o21-o24" aria-label="Permalink to &quot;A6 · O14 / O15 / O16 / O17 / O18 / O19 / O20 / O21 / O24&quot;">​</a></h3><p>竞品重估：Paperclip 的受治理业务动作与恢复证据学习价值高、竞争风险高，但预发布事故使可靠性判断保持审慎；Orca 的多端协作与外部聊天 API 风险中高，跨主机编排尚未完整启用；Orkas 与 Agentlas 的兼容探测/升级价值中高、交付竞争风险中；Vibe Kanban 保留低频观察并核查 sunset 判断，不能据提交认定商业复活。未发现足以改变本轮商业 License 判断的已核验证据。</p><h2 id="覆盖与双源核查" tabindex="-1">覆盖与双源核查 <a class="header-anchor" href="#覆盖与双源核查" aria-label="Permalink to &quot;覆盖与双源核查&quot;">​</a></h2><p>执行起点：2026-11-11 10:24:17 Asia/Shanghai。最近成功轮为 2026-11-09T022534Z；11 月 10 日无成功执行记录，本轮从各来源最后完整成功基线补查，不补造昨日日报。新 main Registry：47 位研究者；人物与仓库多对多关系保留，赵越始终使用此中文名。88 个原始仓库入口查询 commits/issues/releases 共 264 次；首次页满 100 的查询不能算全覆盖，三个高流量 commits 来源另读第二页仍满，历史缺口保留。TSA-AI-Workforce 返回 404，不推测删除或私有；superset 原地址返回迁移，通过仓库 ID 1080370450 核对到 ParadevAI/Paradev，后者本轮工程增量尚未完整核查。部分 release 初次超时，改 10 条重试，未完成历史分页仍记 partial。GitHub PR 状态由详情复核；合入 main 不等于发行包已包含，除明确 RELEASED 条目外均未核验安装交付。没有逐一穷尽 47 人的 X/回复/线程、全部作者主页、Roadmap/Discussion、安全公告及 License 历史，README/源码也非全部仓库逐文件审查；这些维度不可记为无变化或推进基线。</p><p>公开网页独立核查：Cursor changelog（最新显示 11 月 6 日）、Anthropic Engineering（最新显示 11 月 6 日）以及赵越本人主页；这些页面未形成当窗可确认新增。作者/治理主题定向搜索仅是检索结果，不证明全部社交无新增。LangChain 11 月 9–10 日文章及 OpenAI 11 月 10 日政策提供非 GitHub 来源，见 O25/O26；工程事实可由 GitHub 一手材料独立支持，两个 GitHub 链接不算两类来源。</p><ul><li><a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">Cursor</a></li><li><a href="https://www.anthropic.com/engineering" target="_blank" rel="noreferrer">Anthropic Engineering</a></li><li><a href="https://yzhao062.github.io/" target="_blank" rel="noreferrer">Yue Zhao</a></li></ul><p>分类与成果边界：26 项观察；6 组分析；体验/实验为候选，未安装或运行上述应用。已完成本地研究实验 0、文章 0、正式开发评审 0、外部互动 0。CodeFlowMu/FCoP 关联均为待验证研究线索，未生成派工。公开存档只更新两份当日日报与两份索引，网站发布状态以本轮聊天验收回执为准。</p><p>后续人工研究更新：上述 0 项是 10:24 增量核查时的快照。之后我们针对 A2 / O14 运行了 CodeFlowMu 任务提交的隔离故障注入：第一次因目标路径受阻返回错误，文件仍在执行目录，但文件头已经记录进入审查；解除阻塞重试成功且转换记录未重复，成功回执丢失后的再次重发则被阶段检查拒绝。生命周期定向测试 28/28 通过。这是本地 API 的有界实验，不是 Paperclip 复现或线上事故。<a href="/joinwell52/zh/research/2026-11-11-task-moved-after-record">双语研究文章</a> · <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-11-lifecycle-atomicity/00-report.md" target="_blank" rel="noreferrer">公开实验记录</a>。后续人工研究完成实验议题 1、双语文章 1；CodeFlowMu 开发价值按本地评审另记，外部互动未为凑数发送。</p>',126)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
